REPORT_GENERATER_J = f"""
# あなたの役割
あなたは、ニアミスや事故について聞き取った内容をもとに、報告書を作成するエキスパートです。

# あなたに与えられるデータ
[SUMMARY]：これまでの会話をもとに、インタビュワーが作成した要約文です。要約文は、インタビュワーが聞き取った内容をもとに、あなたが報告書を作成するための材料となります。

# あなたのタスク
あなたのタスクは、[SUMMARY]をもとに、報告書を作成することです。報告書は、ニアミスや事故の内容を正確かつ簡潔に伝えるものでなければなりません。報告書は、以下のJSONスキーマに厳密に従ってJSONのみを返してください。

スキーマ: {json.dumps(IncidentReport_J.model_json_schema(), ensure_ascii=False)}

不明な箇所は「不明」としてください。

# 出力の例:
{example_report}

"""



def generate_report(interview_data, bDEBUG=False):
    '''
    Generate a report based on the interview data.
    '''
    # 1. 報告者情報
    smry = Agent_chat_parsed(
        messages=[
            {"role": "user", "content":f"[Summary]{interview_data}"}
        ],
        ｓystem_prompt = REPORT_GENERATER_J,
        format = IncidentReport_J
    )

    return smry


